export function ProgressRing({
  label = "{{label}}",
  value = {{value}},
  color = "{{color}}",
  indeterminate = {{indeterminate}},
}) {
  const circumference = 238.76;
  const offset = circumference - (circumference * value) / 100;
  return (
    <div role="progressbar" aria-label={label} aria-valuemin={0} aria-valuemax={100}
      aria-valuenow={indeterminate ? undefined : value}
      style={{ position: "relative", width: 88, height: 88, font: "11px system-ui, sans-serif", color: "#241430" }}>
      <svg width="88" height="88" viewBox="0 0 88 88" aria-hidden="true">
        <circle cx="44" cy="44" r="38" fill="none" stroke="#24143018" strokeWidth="8" />
        <circle cx="44" cy="44" r="38" fill="none" stroke={color} strokeWidth="8" strokeLinecap="round"
          className={indeterminate ? "pr-circle pr-circle--indeterminate" : "pr-circle"}
          style={{ strokeDasharray: indeterminate ? "60 178.76" : circumference,
            strokeDashoffset: indeterminate ? 0 : offset, transform: "rotate(-90deg)", transformOrigin: "50% 50%" }} />
      </svg>
      <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center",
        justifyContent: "center", textAlign: "center", gap: 2 }}>
        {!indeterminate && <span style={{ fontWeight: 700, fontSize: 15 }}>{value}%</span>}
        <span style={{ opacity: 0.7, maxWidth: 70 }}>{label}</span>
      </div>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .pr-circle { transition: stroke-dashoffset .2s ease; }
          .pr-circle--indeterminate { animation: ring-react-spin 1s linear infinite; }
          @keyframes ring-react-spin { to { transform: rotate(270deg); } }
        }
      `}</style>
    </div>
  );
}
